// shouldRetry waits before a repeated export when err is retryable and attempts are
// left; it reports false when the processor is aborted meanwhile.
func (p *BatchProcessor) shouldRetry(err error, attempt int) bool {
	if attempt >= p.opts.MaxExportRetries || !isRetryableExportError(err) || p.abortCtx.Err() != nil {
		return false
	}
	p.retries.Add(1)
	timer := time.NewTimer(p.retryDelay(attempt))
	defer timer.Stop()
	select {
	case <-timer.C:
		return true
	case <-p.abortCtx.Done():
		return false
	}
}

// fail counts a batch as failed and notifies OnError and OnDrop ("export_failed").
func (p *BatchProcessor) fail(batch []LogRecord, err error) {
	p.failed.Add(int64(len(batch)))
	p.callOnError(err, batch)
	p.notifyDrop(batch, DropReasonExportFailed)
}

func (p *BatchProcessor) callExport(ctx context.Context, batch []LogRecord, opts ExportOptions) (res ExportResult, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = &Error{Code: ErrorCodeUnavailable, Message: fmt.Sprintf("logging.export: exporter panicked: %v", r)} // not retried
		}
	}()
	res, err = p.exporter.Export(ctx, batch, opts)
	if err != nil && (errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled)) {
		err = ContextError("logging.export", err) // TIMEOUT is retryable, CANCELLED is not
	}
	return res, err
}

func isRetryableExportError(err error) bool {
	var e *Error
	return errors.As(err, &e) && e.Retryable
}

func (p *BatchProcessor) drop(recs []LogRecord, reason DropReason) {
	p.dropped.Add(int64(len(recs)))
	p.notifyDrop(recs, reason)
}

func (p *BatchProcessor) notifyDrop(recs []LogRecord, reason DropReason) {
	if p.opts.OnDrop == nil {
		return
	}
	defer func() { _ = recover() }()
	p.opts.OnDrop(recs, reason)
}

func (p *BatchProcessor) callOnError(err error, recs []LogRecord) {
	if p.opts.OnError == nil {
		return
	}
	defer func() { _ = recover() }()
	p.opts.OnError(err, recs)
}
